using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Diagnostics;using System.Collections.Generic;

sealed partial class Companion {

 internal string bridgeFolder,ownerRoot,recordFile;internal bool IsTabbed;internal int revision;internal System.Windows.Forms.Timer bridgeTimer;

 internal string Shared {get{return Environment.GetEnvironmentVariable("JAGO_SUITE_ROOT")??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Jago Studio Suite");}}

 internal void SetupBridge(){bridgeFolder=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TAB_ROOT")??Path.Combine(Shared,"LiveWindows",Guid.NewGuid().ToString());ownerRoot=Environment.GetEnvironmentVariable("JAGO_WORKSPACE_ROOT");Directory.CreateDirectory(bridgeFolder);recordFile=Path.Combine(Shared,"OpenStudios",Process.GetCurrentProcess().Id+".json");PublishRecord();Store.Atomic(Path.Combine(bridgeFolder,"ready.json"),Store.Json.Serialize(new{ready=true,handle=Handle.ToInt64()}));string restore=Path.Combine(bridgeFolder,"restore.json");if(File.Exists(restore)){try{Restore(Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(restore)));File.Move(restore,Path.Combine(bridgeFolder,"restored-"+Guid.NewGuid()+".json"));}catch(Exception e){Tell("Workspace note could not restore: "+e.Message);}}bridgeTimer=new System.Windows.Forms.Timer{Interval=750};bridgeTimer.Tick+=(s,e)=>BridgeTick();bridgeTimer.Start();RegisterConnection();BridgeState();}

 internal void RegisterConnection(){try{string file=Path.Combine(Shared,"connections.json");var all=File.Exists(file)?Store.Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(file)):new Dictionary<string,string>();all["companion"]=Application.ExecutablePath;Store.Atomic(file,Store.Json.Serialize(all));}catch{}}

 internal void PublishRecord(){if(recordFile==null)return;string record=Store.Json.Serialize(new{protocol=1,bridge=2,version=typeof(Companion).Assembly.GetName().Version.ToString(),build=Program.BuildHash,config=Program.Config,started=Process.GetCurrentProcess().StartTime.ToUniversalTime().ToString("o"),pid=Process.GetCurrentProcess().Id,exe=Application.ExecutablePath,studio="companion",id=Path.GetFileName(bridgeFolder),folder=bridgeFolder,owner=ownerRoot,origin="native",name=current==null?"Quick notes":current.Title});Store.Atomic(recordFile,record);Store.Atomic(Path.Combine(Program.Config,"workscape-live.json"),record);}

 internal void BridgeState(){if(bridgeFolder==null)return;Store.Atomic(Path.Combine(bridgeFolder,"state.json"),Store.Json.Serialize(new{dirty=dirty,pending=false,revision=revision++,idleFor=4000,name=current==null?"Quick notes":current.Title}));}
 internal void BridgeTick(){IntPtr active=Native.GetForegroundWindow();if(!IsOwnWindow(active)&&Native.IsWindowVisible(active)&&!Native.IsIconic(active))lastWindow=active;foreach(string file in Directory.GetFiles(bridgeFolder,"command-*.json").OrderBy(File.GetLastWriteTimeUtc)){try{var m=Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));File.Delete(file);BridgeCommand(m);}catch(Exception e){Tell("Workscape: "+e.Message);}}}

 internal void BridgeCommand(Dictionary<string,object> m){string type=Convert.ToString(m["type"]);if(type=="attach"){ownerRoot=Convert.ToString(m["workspace"]);IsTabbed=true;ApplyFloating();Opacity=1;Region=null;TopMost=false;FormBorderStyle=FormBorderStyle.None;MinimumSize=new Size(0,0);Native.SetParent(Handle,new IntPtr(Convert.ToInt64(m["parent"])));Native.SetStyle(Handle,-16,new IntPtr(0x50000000L));Show();Native.MoveWindow(Handle,0,0,Convert.ToInt32(m["width"]),Convert.ToInt32(m["height"]),true);PublishRecord();Store.Atomic(Path.Combine(bridgeFolder,"attached.json"),Store.Json.Serialize(new{handle=Handle.ToInt64()}));}else if(type=="resize")Native.MoveWindow(Handle,0,0,Convert.ToInt32(m["width"]),Convert.ToInt32(m["height"]),true);else if(type=="detach"){DetachToDesktop();Show();Activate();}else if(type=="focus"){if(Convert.ToBoolean(m["active"])){Show();if(view=="Tasks")taskEntry.Focus();else editor.Focus();}else SaveNow();}else if(type=="theme")ApplyTheme(Convert.ToString(m["name"]));else if(type=="capture"){SaveNow();Store.Atomic(Path.Combine(bridgeFolder,"snapshot.json"),Store.Json.Serialize(new{document=Snapshot(),studio="companion"}));}else if(type=="shortcut"){string key=Convert.ToString(m["key"]);bool shift=m.ContainsKey("shift")&&Convert.ToBoolean(m["shift"]);if(notes.Focused){if(key=="Delete")DeleteSelectedPages();else if(key=="z")RestoreDeletedPage();}else if(taskEntry.Focused||search.Focused){TextBoxBase field=taskEntry.Focused?(TextBoxBase)taskEntry:search;if(key=="z"||key=="y")field.Undo();else if(key=="Delete")DeleteText(field);}else if(view=="Tasks"&&tasks.Focused&&key=="Delete")RemoveTask();else if(editor.Focused||view=="Tasks"&&!taskEntry.Focused){if(key=="z")UndoNote(shift);else if(key=="y")UndoNote(true);else if(key=="Delete")DeleteText(editor);}if(key=="s")SaveNow();}else if(type=="close"){if(!SaveNow())return;DetachToDesktop();Hide();Store.Atomic(Path.Combine(bridgeFolder,"released.json"),Store.Json.Serialize(new{ok=true,pid=Process.GetCurrentProcess().Id}));if(!bridgeFolder.StartsWith(Path.Combine(Shared,"LiveWindows")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)){bridgeFolder=Path.Combine(Shared,"LiveWindows",Guid.NewGuid().ToString());Directory.CreateDirectory(bridgeFolder);Store.Atomic(Path.Combine(bridgeFolder,"ready.json"),Store.Json.Serialize(new{ready=true,handle=Handle.ToInt64()}));PublishRecord();}}else if(type=="float"){if(IsTabbed)DetachToDesktop();store.Pref.Top=true;Compact(true);ApplyFloating();var area=Screen.FromPoint(Cursor.Position).WorkingArea;Location=new Point(Math.Max(area.Left,Math.Min(area.Right-Width,area.Right-Width-30)),Math.Max(area.Top,Math.Min(area.Bottom-Height,area.Top+70)));Show();Activate();Store.Atomic(Path.Combine(bridgeFolder,"floating.json"),Store.Json.Serialize(new{ok=true,handle=Handle.ToInt64(),topmost=TopMost}));}else if(type=="compact")Compact(Convert.ToBoolean(m["enabled"]));else if(type=="settings")Settings();else if(type=="test-ui"&&Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TEST_ROOT")!=null){string action=Convert.ToString(m["action"]);if(action=="all-notes")allNotesTab.PerformClick();else if(action=="current-note")currentNoteTab.PerformClick();else if(action=="memo-on"){store.Pref.Memo=true;ApplyFloating();}else if(action=="note-view")SetView("Notes");else if(action=="task-view")SetView("Tasks");else if(action=="select-first"&&notes.Items.Count>0){notes.ClearSelected();notes.SelectedIndex=0;}else if(action=="menu-open"){var menu=top.Items.OfType<ToolStripDropDownItem>().First(x=>x.Text=="Pages");menu.ShowDropDown();}else if(action=="menu-close"){foreach(var menu in top.Items.OfType<ToolStripDropDownItem>())menu.HideDropDown();}else if(action=="new-note")NewNote("Embedded test page","Body retained");else if(action=="delete-note")DeleteSelectedPages();BridgeCommand(new Dictionary<string,object>{{"type","test-status"}});}else if(type=="test-status"&&Environment.GetEnvironmentVariable("JAGO_WORKSPACE_TEST_ROOT")!=null)Store.Atomic(Path.Combine(bridgeFolder,"test-result.json"),Store.Json.Serialize(new{ok=true,name=current==null?"":current.Title,body=editor.Text,tabbed=IsTabbed,compact=CompactLayout,standaloneCompact=store.Pref.Compact,listVisible=!split.Panel1Collapsed,pageVisible=!split.Panel2Collapsed,focus=store.Pref.FocusNote,view=view,quickVisible=quick.Visible,topVisible=top.Visible,menuVisible=top.Items.OfType<ToolStripDropDownItem>().Any(x=>x.DropDown.Visible),width=ClientSize.Width,topmost=TopMost,visible=Visible,handle=Handle.ToInt64()}));BridgeState();}

 internal object Snapshot(){return new{format="jago-companion-note",version=1,name=current==null?"Quick note":current.Title,body=editor.Text};}

 internal void Restore(Dictionary<string,object> data){if(data==null||Convert.ToString(data["format"])!="jago-companion-note"||Convert.ToInt32(data["version"])!=1)throw new Exception("Unsupported note snapshot");string body=Convert.ToString(data["body"]);if(body.Length>262144)throw new Exception("Note snapshot too large");var n=store.Notes.FirstOrDefault(x=>x.Body==body)??store.Create(Convert.ToString(data["name"]),body);SelectNote(n);RefreshNotes();}

 internal void DetachToDesktop(){IsTabbed=false;ownerRoot=null;Native.SetParent(Handle,IntPtr.Zero);Native.SetStyle(Handle,-16,new IntPtr(0x10CF0000L));FormBorderStyle=FormBorderStyle.Sizable;MinimumSize=new Size(330,350);Size=store.Pref.Compact?new Size(430,480):new Size(store.Pref.Width,store.Pref.Height);TopMost=store.Pref.Top;Compact(store.Pref.Compact);ApplyFloating();PublishRecord();Store.Atomic(Path.Combine(bridgeFolder,"detached.json"),Store.Json.Serialize(new{handle=Handle.ToInt64()}));}

 internal void RequestWorkscapeFocus(){if(ownerRoot==null)return;Store.Atomic(Path.Combine(ownerRoot,"action-"+Guid.NewGuid()+".json"),Store.Json.Serialize(new{action="focus",id=Path.GetFileName(bridgeFolder)}));}

 internal void StopBridge(){if(bridgeTimer!=null){bridgeTimer.Stop();bridgeTimer.Dispose();}if(recordFile!=null&&File.Exists(recordFile))File.Delete(recordFile);try{string local=Path.Combine(Program.Config,"workscape-live.json");if(File.Exists(local)&&Convert.ToInt32(Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(local))["pid"])==Process.GetCurrentProcess().Id)File.Delete(local);}catch{}}

}
